+    /**
+     * @return VM endianness, the value of the "sun.cpu.endian" property.
+     */
+    protected String vmEndian() {
+        String endian = System.getProperty("sun.cpu.endian");
+        if (endian != null) {
+            return endian;
+        } else {
+            return errorWithMessage("Can't get 'sun.cpu.endian' property");
+        }
+    }
